void bubble_sort(int* a, size_t n) {
    if (n < 2) return;
    for (size_t i = 0; i + 1 < n; ++i) {
        bool swapped = false;
        for (size_t j = 0; j + 1 < n - i; ++j) {
            if (a[j] > a[j + 1]) {
                int tmp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = tmp;
                swapped = true;
            }
        }
        if (!swapped) break;
    }
}

namespace {

void merge(int* a, size_t lo, size_t mid, size_t hi, int* buf) {
    size_t i = lo, j = mid + 1;
    for (size_t k = lo; k < hi; ++k) buf[k] = a[k];
    for (size_t k = lo; k <= hi; ++k) {
        if (i > mid) {
            a[k] = buf[j++];
        } else if (j > hi) {
            a[k] = buf[i++];
        } else if (buf[i] <= buf[j]) {
            a[k] = buf[i++];
        } else {
            a[k] = buf[j++];
        }
    }
}

void merge_sort_rec(int* a, size_t lo, size_t hi, int* buf) {
    if (hi - lo < 2) return;
    size_t mid = lo + (hi - lo) / 2;
    merge_sort_rec(a, lo, mid, buf);
    merge_sort_rec(a, mid + 1, hi, buf);
    merge(a, lo, mid, hi, buf);
}

}  // namespace

void merge_sort(int* a, size_t n) {
    if (n < 2) return;
    int* buf = new int[n];
    merge_sort_rec(a, 0, n - 1, buf);
    delete[] buf;
}
