#include <vector>

int lcs(const std::string& a, const std::string& b) {
    if (a.empty() || b.empty()) return 0;
    // Iterate over the longer string, keep DP row over the shorter one.
    const std::string& long_s = (a.size() >= b.size()) ? a : b;
    const std::string& short_s = (a.size() >= b.size()) ? b : a;
    std::vector<int> dp(short_s.size() + 1, 0);
    for (size_t i = 1; i <= long_s.size(); ++i) {
        int prev = 0; // dp[j-1] from the previous row
        for (size_t j = 1; j <= short_s.size(); ++j) {
            int tmp = dp[j];
            if (long_s[i - 1] == short_s[j - 1]) {
                dp[j] = prev + 1;
            } else if (dp[j - 1] > dp[j]) {
                dp[j] = dp[j - 1];
            }
            prev = tmp;
        }
    }
    return dp[short_s.size()];
}
