    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e.first;
        int v = e.second;
        if (u < 0 || u >= n || v < 0 || v >= n) {
            continue; // ignore edges with out-of-range endpoints
        }
        adj[u].push_back(v);
        adj[v].push_back(u);
